// V132-venuemap: 2009 Goggle Maps pan disc + Pegman + zoom slider markup, shared by the L11 full map (gmaps-ui.js)
// and the venue maps (venue127-maps.js). Markup only; each caller wires its own handlers.
export const ARROW=d=>`<svg viewBox="0 0 12 12" aria-hidden="true"><path d="${d}" fill="none" stroke="#5578c5" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
export const gmCtlHTML=()=>`<div class="gm-ctl" aria-label="Pan and zoom"><div class="gm-pan"><button class="gm-pan-n" data-pan="ArrowUp" aria-label="Pan up">${ARROW('M2.5 8 L6 4 L9.5 8')}</button><button class="gm-pan-w" data-pan="ArrowLeft" aria-label="Pan left">${ARROW('M8 2.5 L4 6 L8 9.5')}</button><button class="gm-pan-c" data-gm="center" aria-label="Return to my location"><svg viewBox="0 0 14 14" aria-hidden="true"><path d="M4 8V4.5a1 1 0 0 1 2 0V7V3a1 1 0 0 1 2 0v4V3.5a1 1 0 0 1 2 0V8V5.5a1 1 0 0 1 2 0V9c0 2.5-1.6 4-4 4H7.5C5.8 13 5 12 4 10.6L2.4 8.3a1 1 0 0 1 1.6-1z" fill="#fff" stroke="#5578c5" stroke-width="1"/></svg></button><button class="gm-pan-e" data-pan="ArrowRight" aria-label="Pan right">${ARROW('M4 2.5 L8 6 L4 9.5')}</button><button class="gm-pan-s" data-pan="ArrowDown" aria-label="Pan down">${ARROW('M2.5 4 L6 8 L9.5 4')}</button></div>
 <div class="gm-peg" aria-hidden="true"></div><div class="gm-zoom"><button class="gm-zbtn" data-gm="in" aria-label="Zoom in">+</button><div class="gm-track"><span class="gm-ticks"></span><span class="gm-thumb"></span></div><button class="gm-zbtn" data-gm="out" aria-label="Zoom out">−</button></div></div>`;
